section.sourcecode:
MEDIA-GATEWAY-CONTROL DEFINITIONS AUTOMATIC TAGS::= BEGIN
MegacoMessage ::= SEQUENCE { authHeader AuthenticationHeader OPTIONAL, mess Message }
AuthenticationHeader ::= SEQUENCE { secParmIndex SecurityParmIndex, seqNum SequenceNum, ad AuthData }
SecurityParmIndex ::= OCTET STRING(SIZE(4))
SequenceNum ::= OCTET STRING(SIZE(4))
AuthData ::= OCTET STRING (SIZE (12..32))
Message ::= SEQUENCE { version INTEGER(0..99), -- ここで定義するプロトコルのバージョンは1です。 mId MId, -- メッセージ送信元の名前／アドレス messageBody CHOICE { messageError ErrorDescriptor, transactions SEQUENCE OF Transaction }, ... }
MId ::= CHOICE { ip4Address IP4Address, ip6Address IP6Address, domainName DomainName, deviceName PathName, mtpAddress OCTET STRING(SIZE(2..4)), -- mtpAddressのアドレス構造: -- 25 - 15 0 -- | PC | NI | -- 24 - 14 bits 2 bits -- 注: 国際用には14ビットが定義されています。 -- ポイントコードが16ビットまたは24ビットである国内用の -- オプションが2つあります。 -- mtpAddressをオクテット境界にそろえるため、MSB側は0で -- 符号化しなければなりません。 ... }

DomainName ::= SEQUENCE { name IA5String, -- 名前は英数字で始まり、そのあとに英数字、ハイフン、ドットの -- 並びが続きます。2つのドットが連続してはなりません。 portNumber INTEGER(0..65535) OPTIONAL }
IP4Address ::= SEQUENCE { address OCTET STRING (SIZE(4)), portNumber INTEGER(0..65535) OPTIONAL }
IP6Address ::= SEQUENCE { address OCTET STRING (SIZE(16)), portNumber INTEGER(0..65535) OPTIONAL }
PathName ::= IA5String(SIZE (1..64)) -- A.3を参照
Transaction ::= CHOICE { transactionRequest TransactionRequest, transactionPending TransactionPending, transactionReply TransactionReply, transactionResponseAck TransactionResponseAck, -- レスポンスの確認応答を使うかどうかは、下位の -- トランスポートに依存します ... }
TransactionId ::= INTEGER(0..4294967295) -- 32ビット符号なし整数
TransactionRequest ::= SEQUENCE { transactionId TransactionId, actions SEQUENCE OF ActionRequest, ... }
TransactionPending ::= SEQUENCE { transactionId TransactionId, ... }

TransactionReply ::= SEQUENCE { transactionId TransactionId, immAckRequired NULL OPTIONAL, transactionResult CHOICE { transactionError ErrorDescriptor, actionReplies SEQUENCE OF ActionReply }, ... }
TransactionResponseAck ::= SEQUENCE OF TransactionAck TransactionAck ::= SEQUENCE { firstAck TransactionId, lastAck TransactionId OPTIONAL }
ErrorDescriptor ::= SEQUENCE { errorCode ErrorCode, errorText ErrorText OPTIONAL }
ErrorCode ::= INTEGER(0..65535) -- エラーコードに関するIANAの考慮事項は13章を参照
ErrorText ::= IA5String
ContextID ::= INTEGER(0..4294967295)
-- コンテキストのNULL値: 0 -- コンテキストのCHOOSE値: 4294967294 (0xFFFFFFFE) -- コンテキストのALL値: 4294967295 (0xFFFFFFFF)
ActionRequest ::= SEQUENCE { contextId ContextID, contextRequest ContextRequest OPTIONAL, contextAttrAuditReq ContextAttrAuditRequest OPTIONAL, commandRequests SEQUENCE OF CommandRequest }
ActionReply ::= SEQUENCE { contextId ContextID, errorDescriptor ErrorDescriptor OPTIONAL, contextReply ContextRequest OPTIONAL, commandReply SEQUENCE OF CommandReply }

ContextRequest ::= SEQUENCE { priority INTEGER(0..15) OPTIONAL, emergency BOOLEAN OPTIONAL, topologyReq SEQUENCE OF TopologyRequest OPTIONAL, ... }
ContextAttrAuditRequest ::= SEQUENCE { topology NULL OPTIONAL, emergency NULL OPTIONAL, priority NULL OPTIONAL, ... }
CommandRequest ::= SEQUENCE { command Command, optional NULL OPTIONAL, wildcardReturn NULL OPTIONAL, ... }
Command ::= CHOICE { addReq AmmRequest, moveReq AmmRequest, modReq AmmRequest, -- Add、Move、Modifyのリクエストは同じパラメーターを持ちます subtractReq SubtractRequest, auditCapRequest AuditRequest, auditValueRequest AuditRequest, notifyReq NotifyRequest, serviceChangeReq ServiceChangeRequest, ... }
CommandReply ::= CHOICE { addReply AmmsReply, moveReply AmmsReply, modReply AmmsReply, subtractReply AmmsReply, -- Add、Move、Modify、Subtractの応答は同じパラメーターを持ちます auditCapReply AuditReply, auditValueReply AuditReply, notifyReply NotifyReply, serviceChangeReply ServiceChangeReply, ... }

TopologyRequest ::= SEQUENCE { terminationFrom TerminationID, terminationTo TerminationID, topologyDirection ENUMERATED { bothway(0), isolate(1), oneway(2) }, ... }
AmmRequest ::= SEQUENCE { terminationID TerminationIDList, descriptors SEQUENCE OF AmmDescriptor, -- シーケンス内では、各種類の記述子（AmmDescriptorを参照）は -- 高々1つまで許されます。 ... }
AmmDescriptor ::= CHOICE { mediaDescriptor MediaDescriptor, modemDescriptor ModemDescriptor, muxDescriptor MuxDescriptor, eventsDescriptor EventsDescriptor, eventBufferDescriptor EventBufferDescriptor, signalsDescriptor SignalsDescriptor, digitMapDescriptor DigitMapDescriptor, auditDescriptor AuditDescriptor, ... }
AmmsReply ::= SEQUENCE { terminationID TerminationIDList, terminationAudit TerminationAudit OPTIONAL, ... }
SubtractRequest ::= SEQUENCE { terminationID TerminationIDList, auditDescriptor AuditDescriptor OPTIONAL, ... }

AuditRequest ::= SEQUENCE { terminationID TerminationID, auditDescriptor AuditDescriptor, ... }
AuditReply ::= CHOICE { contextAuditResult TerminationIDList, error ErrorDescriptor, auditResult AuditResult, ... }
AuditResult ::= SEQUENCE {
terminationID TerminationID, terminationAuditResult TerminationAudit }
TerminationAudit ::= SEQUENCE OF AuditReturnParameter
AuditReturnParameter ::= CHOICE { errorDescriptor ErrorDescriptor, mediaDescriptor MediaDescriptor, modemDescriptor ModemDescriptor, muxDescriptor MuxDescriptor, eventsDescriptor EventsDescriptor, eventBufferDescriptor EventBufferDescriptor, signalsDescriptor SignalsDescriptor, digitMapDescriptor DigitMapDescriptor, observedEventsDescriptor ObservedEventsDescriptor, statisticsDescriptor StatisticsDescriptor, packagesDescriptor PackagesDescriptor, emptyDescriptors AuditDescriptor, ... }
AuditDescriptor ::= SEQUENCE { auditToken BIT STRING { muxToken(0), modemToken(1), mediaToken(2), eventsToken(3), signalsToken(4), digitMapToken(5), statsToken(6), observedEventsToken(7), packagesToken(8), eventBufferToken(9) } OPTIONAL, ... }

NotifyRequest ::= SEQUENCE
{
   terminationID              TerminationIDList,
   observedEventsDescriptor   ObservedEventsDescriptor,
   errorDescriptor            ErrorDescriptor OPTIONAL,
   ...
}

NotifyReply ::= SEQUENCE
{
   terminationID           TerminationIDList,
   errorDescriptor         ErrorDescriptor OPTIONAL,
   ...
}

ObservedEventsDescriptor ::= SEQUENCE
{
   requestId               RequestID,
   observedEventLst        SEQUENCE OF ObservedEvent
}

ObservedEvent ::= SEQUENCE
{
   eventName            EventName,
   streamID             StreamID OPTIONAL,
   eventParList         SEQUENCE OF EventParameter,
   timeNotation         TimeNotation OPTIONAL,
   ...
}

EventName ::= PkgdName

EventParameter ::= SEQUENCE
{
   eventParameterName      Name,
   value                   Value,
-- extraInfoの使い方はPropertyParmに関するコメントを参照
   extraInfo CHOICE
   {
      relation Relation,
      range    BOOLEAN,
      sublist  BOOLEAN
   } OPTIONAL,
   ...
}

ServiceChangeRequest ::= SEQUENCE
{
   terminationID           TerminationIDList,
   serviceChangeParms      ServiceChangeParm,
   ...
}

ServiceChangeReply ::= SEQUENCE
{
   terminationID           TerminationIDList,
   serviceChangeResult     ServiceChangeResult,
   ...
}

-- ServiceChangeResultでは、必須のパラメーターはありません。そのため、
-- ServiceChangeParmとServiceChangeResParmを区別しています。

ServiceChangeResult ::= CHOICE
{
   errorDescriptor            ErrorDescriptor,
   serviceChangeResParms      ServiceChangeResParm
}

WildcardField ::= OCTET STRING(SIZE(1))

TerminationID ::= SEQUENCE
{
   wildcard SEQUENCE OF WildcardField,
   id    OCTET STRING(SIZE(1..8)),
   ...
}
-- ワイルドカード指定の仕組みの説明はA.1を参照。
-- Termination ID 0xFFFFFFFFFFFFFFFFはルートターミネーションを
-- 示します。

TerminationIDList ::= SEQUENCE OF TerminationID

MediaDescriptor ::= SEQUENCE
{

   termStateDescr TerminationStateDescriptor OPTIONAL,
   streams     CHOICE
   {
      oneStream      StreamParms,
      multiStream    SEQUENCE OF StreamDescriptor
   } OPTIONAL,
   ...
}

StreamDescriptor ::= SEQUENCE { streamID StreamID, streamParms StreamParms }
StreamParms ::= SEQUENCE { localControlDescriptor LocalControlDescriptor OPTIONAL, localDescriptor LocalRemoteDescriptor OPTIONAL, remoteDescriptor LocalRemoteDescriptor OPTIONAL, ... }
LocalControlDescriptor ::= SEQUENCE {
streamMode StreamMode OPTIONAL, reserveValue BOOLEAN OPTIONAL, reserveGroup BOOLEAN OPTIONAL, propertyParms SEQUENCE OF PropertyParm, ... }
StreamMode ::= ENUMERATED { sendOnly(0), recvOnly(1), sendRecv(2), inactive(3), loopBack(4), ... }
-- PropertyParmでは、valueはオクテット文字列のSEQUENCE OFです。 -- MGCが送信する場合、次のように解釈します: -- 空のシーケンスはCHOOSEを意味します -- 要素が1つのシーケンスは値を指定します -- sublistフィールドが選択されていない場合、より長いシーケンスは -- 「値のうちの1つを選ぶ」ことを意味します（つまり、value1 OR -- value2 OR ...） -- sublistフィールドが選択されている場合、 -- 要素が2つ以上のシーケンスは、リスト値のプロパティーの値を -- 符号化します（つまり、value1 AND value2 AND ...）。 -- relationフィールドは、valueシーケンスの長さが1の場合にのみ -- 選択できます。これは、MGがプロパティーの値を選ばなければ -- ならないことを示します。たとえば、x > 3（relationに -- greaterThanの値を使用）は、プロパティーxについて3より大きい -- 任意の値を選ぶようMGに指示します。 -- rangeフィールドは、valueシーケンスの長さが2の場合にのみ -- 選択できます。これは、valueシーケンスの最初のオクテットと -- 末尾のオクテットの間の範囲（境界値を含む）から、MGが値を -- 選ばなければならないことを示します。 -- MGが送信する場合、複数の値、範囲、またはrelationフィールドを -- 含めてよいのは、AuditCapabilityリクエストに対するレスポンス -- だけです。
PropertyParm ::= SEQUENCE { name PkgdName, value SEQUENCE OF OCTET STRING, extraInfo CHOICE { relation Relation, range BOOLEAN, sublist BOOLEAN } OPTIONAL, ... }

Name ::= OCTET STRING(SIZE(2))
PkgdName ::= OCTET STRING(SIZE(4)) -- パッケージ名（2オクテット）と、プロパティー名、イベント名、 -- シグナル名または統計ID（2オクテット）を表します。 -- パッケージをワイルドカードで指定するには、先頭の2オクテットに -- 0xFFFFを使います。chooseは許されません。附属書Cで規定する -- ネイティブなプロパティータグを参照するには、先頭の2オクテットに -- 0x0000を使います。 -- プロパティー、イベント、シグナル、または統計IDをワイルド -- カードで指定するには、末尾の2オクテットに0xFFFFを使います。 -- chooseは許されません。 -- パッケージ名のワイルドカード指定は、プロパティー、イベント、 -- シグナル、または統計IDもワイルドカードで指定されている場合 -- にのみ許されます。
Relation ::= ENUMERATED { greaterThan(0), smallerThan(1), unequalTo(2), ... }
LocalRemoteDescriptor ::= SEQUENCE { propGrps SEQUENCE OF PropertyGroup, ... }
PropertyGroup ::= SEQUENCE OF PropertyParm
TerminationStateDescriptor ::= SEQUENCE { propertyParms SEQUENCE OF PropertyParm, eventBufferControl EventBufferControl OPTIONAL, serviceState ServiceState OPTIONAL, ... }
EventBufferControl ::= ENUMERATED { off(0), lockStep(1), ... }
ServiceState ::= ENUMERATED
{ test(0), outOfSvc(1), inSvc(2), ... }

MuxDescriptor ::= SEQUENCE { muxType MuxType, termList SEQUENCE OF TerminationID, nonStandardData NonStandardData OPTIONAL, ... }
MuxType ::= ENUMERATED { h221(0), h223(1), h226(2), v76(3), ... }
StreamID ::= INTEGER(0..65535) -- 16ビット符号なし整数
EventsDescriptor ::= SEQUENCE { requestID RequestID OPTIONAL, -- eventListが空でない場合、RequestIDが -- 存在しなければなりません eventList SEQUENCE OF RequestedEvent, ... }
RequestedEvent ::= SEQUENCE { pkgdName PkgdName, streamID StreamID OPTIONAL, eventAction RequestedActions OPTIONAL, evParList SEQUENCE OF EventParameter, ... }
RequestedActions ::= SEQUENCE { keepActive BOOLEAN OPTIONAL, eventDM EventDM OPTIONAL, secondEvent SecondEventsDescriptor OPTIONAL, signalsDescriptor SignalsDescriptor OPTIONAL, ... }

EventDM ::= CHOICE { digitMapName DigitMapName, digitMapValue DigitMapValue }
SecondEventsDescriptor ::= SEQUENCE { requestID RequestID OPTIONAL, eventList SEQUENCE OF SecondRequestedEvent, ... }
SecondRequestedEvent ::= SEQUENCE { pkgdName PkgdName, streamID StreamID OPTIONAL, eventAction SecondRequestedActions OPTIONAL, evParList SEQUENCE OF EventParameter, ... }
SecondRequestedActions ::= SEQUENCE { keepActive BOOLEAN OPTIONAL, eventDM EventDM OPTIONAL, signalsDescriptor SignalsDescriptor OPTIONAL, ... }
EventBufferDescriptor ::= SEQUENCE OF EventSpec
EventSpec ::= SEQUENCE { eventName EventName, streamID StreamID OPTIONAL, eventParList SEQUENCE OF EventParameter, ... }
SignalsDescriptor ::= SEQUENCE OF SignalRequest
SignalRequest ::=CHOICE { signal Signal, seqSigList SeqSigList, ... }

SeqSigList ::= SEQUENCE { id INTEGER(0..65535), signalList SEQUENCE OF Signal }
Signal ::= SEQUENCE { signalName SignalName, streamID StreamID OPTIONAL, sigType SignalType OPTIONAL, duration INTEGER (0..65535) OPTIONAL, notifyCompletion NotifyCompletion OPTIONAL, keepActive BOOLEAN OPTIONAL, sigParList SEQUENCE OF SigParameter, ... }
SignalType ::= ENUMERATED { brief(0), onOff(1), timeOut(2), ... }
SignalName ::= PkgdName
NotifyCompletion ::= BIT STRING { onTimeOut(0), onInterruptByEvent(1), onInterruptByNewSignalDescr(2), otherReason(3) }
SigParameter ::= SEQUENCE { sigParameterName Name, value Value, -- extraInfoの使い方はPropertyParmに関するコメントを参照 extraInfo CHOICE { relation Relation, range BOOLEAN, sublist BOOLEAN
} OPTIONAL, ... }

-- すべてのイベントを含むAuditCapReplyでは、RequestIDはALLに -- することになります（SHALL）。 -- ALLは0xffffffffで表します。
RequestID ::= INTEGER(0..4294967295) -- 32ビット符号なし整数
ModemDescriptor ::= SEQUENCE { mtl SEQUENCE OF ModemType, mpl SEQUENCE OF PropertyParm, nonStandardData NonStandardData OPTIONAL }
ModemType ::= ENUMERATED { v18(0), v22(1), v22bis(2), v32(3), v32bis(4), v34(5), v90(6), v91(7), synchISDN(8), ... }
DigitMapDescriptor ::= SEQUENCE { digitMapName DigitMapName OPTIONAL, digitMapValue DigitMapValue OPTIONAL }
DigitMapName ::= Name
DigitMapValue ::= SEQUENCE { startTimer INTEGER(0..99) OPTIONAL, shortTimer INTEGER(0..99) OPTIONAL, longTimer INTEGER(0..99) OPTIONAL, digitMapBody IA5String, -- 単位は、start、short、longタイマーでは秒、durationタイマー -- では100ミリ秒です。したがって、start、short、longは1秒から -- 99秒、durationは100msから9.9sの範囲になります -- ディジットマップの構文の説明はA.3を参照 ... }

ServiceChangeParm ::= SEQUENCE { serviceChangeMethod ServiceChangeMethod, serviceChangeAddress ServiceChangeAddress OPTIONAL, serviceChangeVersion INTEGER(0..99) OPTIONAL, serviceChangeProfile ServiceChangeProfile OPTIONAL, serviceChangeReason Value, -- serviceChangeReasonは、数値の理由コードと、省略可能な -- テキストの説明からなります。 -- serviceChangeReasonは、10進数の理由コードと、そのあとに -- 省略可能な1個の空白文字とテキストの説明文字列が続く文字列に -- することになります（SHALL）。 -- この文字列は、まずIA5StringとしてBER符号化されます。 -- このBER符号化の結果は、さらにASN.1のOCTET STRING型として -- 符号化され、パッケージ要素の場合と同様に値を「二重に包み」 -- ます。 serviceChangeDelay INTEGER(0..4294967295) OPTIONAL, -- 32ビット符号なし整数 serviceChangeMgcId MId OPTIONAL, timeStamp TimeNotation OPTIONAL, nonStandardData NonStandardData OPTIONAL, ... }
ServiceChangeAddress ::= CHOICE { portNumber INTEGER(0..65535), -- TCP/UDPポート番号 ip4Address IP4Address, ip6Address IP6Address, domainName DomainName, deviceName PathName, mtpAddress OCTET STRING(SIZE(2..4)), ... }
ServiceChangeResParm ::= SEQUENCE { serviceChangeMgcId MId OPTIONAL, serviceChangeAddress ServiceChangeAddress OPTIONAL, serviceChangeVersion INTEGER(0..99) OPTIONAL, serviceChangeProfile ServiceChangeProfile OPTIONAL, timestamp TimeNotation OPTIONAL, ... }
ServiceChangeMethod ::= ENUMERATED
{ failover(0), forced(1), graceful(2), restart(3), disconnected(4), handOff(5), ... }

ServiceChangeProfile ::= SEQUENCE { profileName IA5String(SIZE (1..67)) -- ABNFに合わせて、名前に64文字、"/"に1文字、バージョンに2文字 }
PackagesDescriptor ::= SEQUENCE OF PackagesItem
PackagesItem ::= SEQUENCE { packageName Name, packageVersion INTEGER(0..99), ... }
StatisticsDescriptor ::= SEQUENCE OF StatisticsParameter
StatisticsParameter ::= SEQUENCE { statName PkgdName, statValue Value OPTIONAL }
NonStandardData ::= SEQUENCE { nonStandardIdentifier NonStandardIdentifier, data OCTET STRING }
NonStandardIdentifier ::= CHOICE { object OBJECT IDENTIFIER, h221NonStandard H221NonStandard, experimental IA5String(SIZE(8)), -- 先頭の2文字は"X-"または"X+"にすべきです ... }
H221NonStandard ::= SEQUENCE { t35CountryCode1 INTEGER(0..255), t35CountryCode2 INTEGER(0..255), -- 国。T.35に従う t35Extension INTEGER(0..255), -- 国ごとに割り当て manufacturerCode INTEGER(0..65535), -- 国ごとに割り当て ... }

TimeNotation ::= SEQUENCE { date IA5String(SIZE(8)), -- yyyymmdd形式 time IA5String(SIZE(8)) -- hhmmssss形式 -- ISO 8601:1988に従う }
Value ::= SEQUENCE OF OCTET STRING
END

section.artwork:
MEGACO/1 [124.124.124.222] Transaction = 9998 {
    Context = - {
        ServiceChange = ROOT {Services {
            Method=Restart,
            ServiceChangeAddress=55555, Profile=ResGW/1}
        }
    } }

MEGACO/1 [123.123.123.4]:55555 Reply = 9998 {
   Context = - {ServiceChange = ROOT {
     Services {ServiceChangeAddress=55555, Profile=ResGW/1} } } }

MEGACO/1 [123.123.123.4]:55555 Transaction = 9999 {
    Context = - {
        Modify = A4444 {
            Media { Stream = 1 {
                     LocalControl {
                         Mode = SendReceive,
                         tdmc/gain=2,  ; in dB,
                         tdmc/ec=on
                     },
                 }
            },
            Events = 2222 {al/of(strict=state)}
        }
    } }

MEGACO/1 [123.123.123.4]:55555 Transaction = 10001 {
    Context = - {
        Modify = A4444 {
            Events = 2223 {
                al/on(strict=state), dd/ce {DigitMap=Dialplan0}
            },
            Signals {cg/dt},
            DigitMap= Dialplan0{ (0| 00|[1-
7]xxx|8xxxxxxx|Fxxxxxxx|Exx|91xxxxxxxxxx|9011x.)}
        }
    } }

MEGACO/1 [123.123.123.4]:55555 Transaction = 10003 {
    Context = $ {
       Add = A4444,
       Add = $ {
           Media {
             Stream = 1 {
                  LocalControl {
                      Mode = ReceiveOnly,
                      nt/jit=40 ; in ms
                  },
                  Local { v=0 c=IN IP4 $ m=audio $ RTP/AVP 4
a=ptime:30 v=0 c=IN IP4 $ m=audio $ RTP/AVP 0
                  }
             }
          }
       }
    } }

MEGACO/1 [124.124.124.222]:55555 Reply = 10003 {
   Context = 2000 {
      Add = A4444,
      Add=A4445{
         Media {
             Stream = 1 {
                 Local { v=0 o=- 2890844526 2890842807 IN IP4
124.124.124.222 s=- t= 0 0 c=IN IP4 124.124.124.222 m=audio 2222
RTP/AVP 4 a=ptime:30 a=recvonly
                 } ; RTP profile for G.723.1 is 4
             }
         }
      }
   } }

MEGACO/1 [123.123.123.4]:55555 Transaction = 50003 {
    Context = $ {
       Add = A5555  { Media {
            Stream = 1 {
                 LocalControl {Mode = SendReceive} }},
      Events=1234{al/of(strict=state)},
            Signals {al/ri}
            },
       Add  = $ {Media {
            Stream = 1 {
                 LocalControl {
                    Mode = SendReceive,
                    nt/jit=40 ; in ms
                 },
                 Local { v=0 c=IN IP4 $ m=audio $ RTP/AVP 4
a=ptime:30
                 },
                 Remote { v=0 c=IN IP4 124.124.124.222 m=audio 2222
RTP/AVP 4 a=ptime:30
                 } ; RTP profile for G.723.1 is 4
             }
          }
      }
   } }

MEGACO/1 [123.123.123.4]:55555 Transaction = 10005 {
  Context = 2000 {
    Modify = A4444 {
      Signals {cg/rt}
    },
    Modify = A4445 {
       Media {
            Stream = 1 {
                Remote { v=0 o=- 7736844526 7736842807 IN IP4
125.125.125.111 s=- t= 0 0 c=IN IP4 125.125.125.111 m=audio 1111
RTP/AVP 4
                }
            } ; RTP profile for G723.1 is 4
        }
    }
  } }

MEGACO/1 [123.123.123.4]:55555 Transaction = 50006 {
   Context = 5000 {
      Modify = A5555 {
         Events = 1235 {al/on(strict=state)},
         Signals { } ; to turn off ringing
      }
   } }

MEGACO/1 [123.123.123.4]:55555 Transaction = 10006 {
   Context = 2000 {
      Modify = A4445 {
         Media {
            Stream = 1 {
               LocalControl {
                  Mode=SendReceive
               }
            }
         }
      },
      Modify = A4444 {
         Signals { }
      }
   } }

MEGACO/1 [123.123.123.4]:55555 Transaction = 50007 {
   Context = - {AuditValue = A5556{
      Audit{Media, DigitMap, Events, Signals, Packages, Statistics }}
   } }

MEGACO/1 [125.125.125.111]:55555 Reply = 50007 {
   Context = - { AuditValue = A5556 {
          Media {
             TerminationState { ServiceStates = InService,
         Buffer = OFF },
       Stream = 1 {
                 LocalControl { Mode = SendReceive,
                    nt/jit=40 },
                 Local { v=0 o=- 7736844526 7736842807 IN IP4
125.125.125.111 s=- t= 0 0 c=IN IP4 125.125.125.111 m=audio 1111
RTP/AVP  4 a=ptime:30
                },
                 Remote { v=0 o=- 2890844526 2890842807 IN IP4
124.124.124.222 s=- t= 0 0 c=IN IP4 124.124.124.222 m=audio 2222
RTP/AVP  4 a=ptime:30
                 } } },
           Events,
        Signals,
        DigitMap,
       Packages {nt-1, rtp-1},
          Statistics { rtp/ps=1200,  ; packets sent
                       nt/os=62300, ; octets sent
                       rtp/pr=700, ; packets received
                       nt/or=45100, ; octets received
                       rtp/pl=0.2,  ; % packet loss
                       rtp/jit=20,
                       rtp/delay=40 } ; avg latency
       }
    } }

MEGACO/1 [123.123.123.4]:55555 Transaction = 50009 {
   Context = 5000 {
      Subtract = A5555 {Audit{Statistics}},
      Subtract = A5556 {Audit{Statistics}}
   } }

MEGACO/1 [125.125.125.111]:55555 Reply = 50009 {
   Context = 5000 {
     Subtract = A5555 {
          Statistics {
             nt/os=45123, ; Octets Sent
             nt/dur=40 ; in seconds
             }
       },
       Subtract = A5556 {
          Statistics {
             rtp/ps=1245, ; packets sent
             nt/os=62345, ; octets sent
             rtp/pr=780, ; packets received
             nt/or=45123, ; octets received
             rtp/pl=10, ;  % packets lost
             rtp/jit=27,
             rtp/delay=48 ; average latency
          }
       }
   } }
